import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const filters = ['All', 'Reading', 'Read', 'Want to read'];

describe('ChipBar', () => {
  it('renders a chip for each filter option', () => {
    render(<ChipBar filters={filters} selected={[]} onSelectionChange={vi.fn()} />);
    for (const label of filters) {
      expect(screen.getByRole('button', { name: label })).toBeInTheDocument();
    }
  });

  it('chips not in selected have aria-pressed false', () => {
    render(<ChipBar filters={filters} selected={[]} onSelectionChange={vi.fn()} />);
    for (const label of filters) {
      expect(screen.getByRole('button', { name: label })).toHaveAttribute('aria-pressed', 'false');
    }
  });

  it('chips in selected have aria-pressed true', () => {
    render(<ChipBar filters={filters} selected={['Reading']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('calls onSelectionChange with newly selected value when an unselected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(<ChipBar filters={filters} selected={[]} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['Reading']);
  });

  it('calls onSelectionChange without value when an already-selected chip is clicked', async () => {
    const handleChange = vi.fn();
    render(<ChipBar filters={filters} selected={['Reading']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith([]);
  });

  it('toggling one chip does not affect other selected chips', async () => {
    const handleChange = vi.fn();
    render(
      <ChipBar filters={filters} selected={['Reading', 'Read']} onSelectionChange={handleChange} />
    );
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledWith(['Read']);
  });
});

