import { renderHook, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

afterEach(() => {
  vi.restoreAllMocks();
});

describe('useBooks', () => {
  it('starts in loading state with no data and no error', () => {
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions to loaded state and returns books array', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(Array.isArray(result.current.data)).toBe(true);
    expect(result.current.error).toBeNull();
  });

  it('clears loading flag after getBooks resolves', async () => {
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    await waitFor(() => expect(result.current.loading).toBe(false));
  });

  it('sets error and clears data when getBooks rejects', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce(new Error('load failed'));
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.data).toBeNull();
  });

  it('clears loading flag after getBooks rejects', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValueOnce(new Error('load failed'));
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
  });
});

